import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleList } from './PeopleList';
import { PersonForm } from './PersonForm';

export const contributions = [
  HomeMain.fill({ order: 10, Component: PersonForm }),
  HomeMain.fill({ order: 20, Component: PeopleList }),
];
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useEditingPerson, usePeople } from './people';

// Every person on the sheet, in the order they were added, each with their name and grade and
// the columns features add (slots/defs/personColumns.ts).
export function PeopleList() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setEditing] = useEditingPerson();
  const people = usePeople();

  if (!user || !sheet) return null;

  return (
    <table data-testid="people">
      <thead>
        <tr>
          <th>Name</th>
          <th>Grade</th>
          <PersonColumnHeads.Slot />
          <th />
        </tr>
      </thead>
      <tbody>
        {(people.data ?? []).map((p) => (
          <tr key={p.id} data-testid={`person-row-${p.id}`}>
            <td data-testid="person-name" style={{ whiteSpace: 'pre' }}>
              {p.name}
            </td>
            <td data-testid="person-grade">{p.grade}</td>
            <PersonColumns.Slot person={p} />
            <td>
              <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(p.id)}>
                Edit
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import { sheetKey, useCurrentSheet } from '../session/session';

export const GRADES = ['A', 'B', 'C'] as const;

/**
 * A person on the sheet as the store holds them; `version` counts their saves. `statementCount` counts
 * the statements taken of them; `statedTotal` is the last one's due-total and `statementDate` the
 * sheet's today when it was taken, both null before the first.
 */
export type Person = {
  id: number;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
};

/** The fields the person form submits. */
export type PersonInput = { name: string; grade: string };

/** The query key for the sheet's people; under sheetKey, so re-loading the sheet re-reads them. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open in the person form, if any. */
export const useEditingPerson = () => useSearchParam('person', asNumber);
import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useOneAtATime } from '../../query/useOneAtATime';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { GRADES, peopleKey, useEditingPerson, usePeople } from './people';
import type { Person, PersonInput } from './people';

const EMPTY: PersonInput = { name: '', grade: 'A' };

// Adds a person, or — while a person's editor is open — saves that person's changes. Opening an
// editor fills the form with the person's values and remembers the version it loaded: a save over
// someone else's later save is refused, and the form then shows the current values to save again.
export function PersonForm() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [editing, setEditing] = useEditingPerson();
  const people = usePeople();
  const [form, setForm] = useState<PersonInput>(EMPTY);
  const [error, setError] = useState('');
  const filledFor = useRef<number | undefined>(undefined);
  const version = useRef<number | undefined>(undefined);
  const once = useOneAtATime();
  const queryClient = useQueryClient();

  // Fill the form once per opened editor; close an editor whose person is not on this sheet.
  useEffect(() => {
    if (editing === undefined) {
      filledFor.current = undefined;
      return;
    }
    if (!people.data || filledFor.current === editing) return;
    const person = people.data.find((p) => p.id === editing);
    if (!person) {
      setEditing(undefined);
      return;
    }
    filledFor.current = editing;
    version.current = person.version;
    setForm({ name: person.name, grade: person.grade });
    setError('');
  }, [editing, people.data, setEditing]);

  const close = () => {
    setEditing(undefined);
    setForm(EMPTY);
    setError('');
  };

  const save = useMutation({
    mutationFn: (input: PersonInput) =>
      editing === undefined
        ? postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people?user=${encodeURIComponent(user)}`, input)
        : putJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${editing}?user=${encodeURIComponent(user)}`, {
            ...input,
            version: version.current,
          }),
    onSuccess: async () => {
      close();
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
    onError: async (e, input) => {
      if (e instanceof HttpError && e.status === 409) {
        // Someone else saved this person since the editor loaded it: show what is stored now.
        await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
        const current = queryClient.getQueryData<Person[]>(peopleKey(sheet))?.find((p) => p.id === editing);
        if (current) {
          version.current = current.version;
          setForm({ name: current.name, grade: current.grade });
        }
        setError('Someone else saved this person meanwhile; the form now shows their values.');
        return;
      }
      const key = input.name.trim().toLowerCase();
      const taken = people.data?.some((p) => p.id !== editing && p.name.trim().toLowerCase() === key);
      setError(taken ? 'That name is already in use.' : 'That person could not be saved.');
    },
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!form.name.trim()) {
      setError('Type a name.');
      return;
    }
    once(() => save.mutateAsync(form));
  };

  const change = (patch: Partial<PersonInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  return (
    <form onSubmit={submit} data-testid="person-form">
      <input
        data-testid="person-form-name"
        placeholder="Name"
        value={form.name}
        onChange={(e) => change({ name: e.target.value })}
      />
      <select
        data-testid="person-form-grade"
        value={form.grade}
        onChange={(e) => change({ grade: e.target.value })}
      >
        {GRADES.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing === undefined ? 'Add person' : 'Save person'}
      </button>
      {editing !== undefined && (
        <button type="button" data-testid="person-form-cancel" onClick={close}>
          Cancel
        </button>
      )}
      {error && <span data-testid="person-form-error">{error}</span>}
    </form>
  );
}
import { defineSlot } from '../Slot';
import type { Person } from '../../features/people/people';

/** Extra column headers of the people table: each contribution renders its own <th>. */
export const PersonColumnHeads = defineSlot('people.columnHeads');

/** Extra cells of a person's row, in the same order as PersonColumnHeads: each renders its own <td>. */
export const PersonColumns = defineSlot<{ person: Person }>('people.columns');
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { ClaimStated } from './ClaimStated';
import { PersonStatement } from './PersonStatement';

export const contributions = [
  PersonColumnHeads.fill({ order: 17, Component: () => <th>Statements</th> }),
  PersonColumns.fill({ order: 17, Component: PersonStatement }),
  ClaimRowValues.fill({ order: 12, Component: ClaimStated }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useOneAtATime } from '../../query/useOneAtATime';
import { claimsKey } from '../claims/claims';
import { peopleKey } from '../people/people';
import type { Person } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';

// A person's statements: how many were taken, the last one's due-total and date, and the button that
// takes one — recording their due-total now and binding each counting claim to its figure now.
export function PersonStatement({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const take = useMutation({
    mutationFn: () =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement?user=${encodeURIComponent(user)}`,
        {},
      ),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
    },
    onError: () => setError('The statement could not be taken.'),
  });

  return (
    <td>
      <span data-testid="person-statement-count">{person.statementCount}</span>{' '}
      <span data-testid="person-stated-total">{person.statedTotal ?? ''}</span>{' '}
      <span data-testid="person-statement-date">{person.statementDate ?? ''}</span>{' '}
      <button
        type="button"
        data-testid="person-statement"
        disabled={take.isPending}
        onClick={() => {
          setError('');
          once(() => take.mutateAsync());
        }}
      >
        Statement
      </button>
      {error && <span data-testid="person-error">{error}</span>}
    </td>
  );
}

